const { NPCID } = Terraria.ID;
const Main = Terraria.Main;
const DRAW_STRING = 'void DrawString(SpriteFont spriteFont, string text, Vector2 position, Color color, float rotation, Vector2 origin, float scale, SpriteEffects effects, float layerDepth)';

// O que dá para fazer no desenho das barras de chefe, inclusive as do jogo
// (o ExampleGlobalBossBar do tModLoader). Aqui, a do Olho de Cthulhu.
export class ExampleGlobalBossBar extends GlobalBossBar {
    PreDraw(spriteBatch, npc, drawParams) {
        if (npc.type === NPCID.EyeofCthulhu) {
            drawParams.IconColor = Color.new(Main.DiscoR, Main.DiscoG, Main.DiscoB);
            drawParams.BarColor = Color.Lerp(Color.White, Color.Transparent, Math.sin(Main.GameUpdateCount / 50));
        }

        return true;
    }

    PostDraw(spriteBatch, npc, drawParams) {
        if (npc.type !== NPCID.EyeofCthulhu) return;

        const text = 'GlobalBossBar Showcase';
        const font = Terraria.GameContent.FontAssets.MouseText.Value;
        const size = font['Vector2 MeasureString(string text)'](text);
        // Centrado na barra e abaixo dela: no celular a barra do jogo fica logo
        // embaixo do minimapa (no tModLoader o texto vai acima).
        const position = Vector2.new(drawParams.BarCenter.X - size.X / 2, drawParams.BarCenter.Y - size.Y / 2 + 30);
        spriteBatch[DRAW_STRING](font, text, position, Color.White, 0, Vector2.Zero, 1, 0, 0);
    }
}

const { BuffID } = Terraria.ID;
const Main = Terraria.Main;
const LocalizedDuration = Terraria.Lang['string LocalizedDuration(TimeSpan time, bool abbreviated, bool showAllAvailableUnits)'];
const FromSeconds = System.TimeSpan['TimeSpan FromSeconds(double value)'];
const NewText = Main['void NewText(string newText, byte R, byte G, byte B, bool onlyCurrentPlayer)'];

// Código para todos os buffs, os do jogo também (o ExampleGlobalBuff do tModLoader).
export class ExampleGlobalBuff extends GlobalBuff {
    static #randomText = '';
    static #randomType = 0;

    // Com mais de 5 buffs, o Congelado (Chilled) dura no máximo 3 segundos.
    UpdatePlayer(type, player, buffIndex) {
        if (type !== BuffID.Chilled || buffIndex.value < 5) return;

        const limit = 3 * 60;
        if (player.buffTime[buffIndex.value] > limit) player.buffTime[buffIndex.value] = limit;
    }

    PreDraw(spriteBatch, type, buffIndex, drawParams) {
        // A Fogueira muda de cor e treme.
        if (type === BuffID.Campfire) {
            drawParams.DrawColor = Color.Multiply(Color.new(Main.DiscoR, Main.DiscoG, Main.DiscoB), Main.buffAlpha[buffIndex]);

            const shakeX = Rand.Next(-2, 3), shakeY = Rand.Next(-2, 3);
            drawParams.Position.X += shakeX;
            drawParams.Position.Y += shakeY;
            drawParams.TextPosition.X += shakeX;
            drawParams.TextPosition.Y += shakeY;
        }

        // O texto do tempo sobe e desce 6 pixels na Regeneração, na Pele de
        // Ferro e na Rapidez, cada ícone 4 quadros atrás do anterior.
        if (Main.EquipPage !== 2 && (type === BuffID.Regeneration || type === BuffID.Ironskin || type === BuffID.Swiftness)) {
            const interval = 60;
            const time = ((Main.GameUpdateCount + 4 * buffIndex) % interval) / interval;
            drawParams.TextPosition.Y += Math.trunc(6 * time);
        }

        return true;
    }

    ModifyBuffText(type, buffName, tip, rare) {
        const player = Main.player[Main.myPlayer];
        const index = player.FindBuffIndex(type);
        if (index < 0 || index >= player.buffTime.length) return;

        // O tempo que falta, em todo buff que tem tempo. A Defesa de Exemplo já
        // mostra o dela (ModifyBuffText do próprio ModBuff).
        const time = new Ref(0);
        if (type !== ModContent.BuffType('ExampleDefenseBuff') && Main.TryGetBuffTime(index, time) && time.value > 2) {
            const text = LocalizedDuration(FromSeconds(Math.floor(time.value / 60)), false, true);
            tip.value += '\n' + ModLocalization.Translate('CustomText.RemainingTime').replace('{0}', text);
        }

        // Com Sugar Rush (a fatia de bolo), o nome dos buffs embaralha.
        if (player.FindBuffIndex(BuffID.SugarRush) >= 0 && buffName.value.length > 2) {
            if (Main.GameUpdateCount % 10 === 0 || ExampleGlobalBuff.#randomType !== type) {
                if (ExampleGlobalBuff.#randomType !== type) {
                    ExampleGlobalBuff.#randomText = buffName.value;
                    ExampleGlobalBuff.#randomType = type;
                }
                const characters = [...ExampleGlobalBuff.#randomText];
                const n = characters.length;
                const swaps = Rand.Next(1, Math.floor(n / 2));
                for (let swap = 0; swap < swaps; swap++) {
                    const a = Rand.Next(n - 1);
                    const b = Rand.Next(a + 1, n);
                    [characters[a], characters[b]] = [characters[b], characters[a]];
                }
                ExampleGlobalBuff.#randomText = characters.join('');
            }
            buffName.value = ExampleGlobalBuff.#randomText;
        }
    }

    // Parado, o jogador não cancela a Defesa de Exemplo tocando no ícone.
    RightClick(type, buffIndex) {
        const player = Main.player[Main.myPlayer];
        if (type === ModContent.BuffType('ExampleDefenseBuff') && player.velocity.X === 0 && player.velocity.Y === 0) {
            NewText(ModLocalization.Translate('CustomText.CannotCancel'), 255, 255, 255, false);
            return false;
        }

        return true;
    }
}

const { ItemID, DustID } = Terraria.ID;
const Main = Terraria.Main;
const NewDust = Terraria.Dust['int NewDust(Vector2 Position, int Width, int Height, int Type, float SpeedX, float SpeedY, int Alpha, Color newColor, float Scale)'];

// Código para todas as receitas, as do jogo também. O tModLoader 1.4 não tem
// mais esta classe (cada receita tem o AddCondition e os callbacks, ver
// ExampleRecipes); o Bunny Loader mantém os três ganchos dela.
export class ExampleGlobalRecipe extends GlobalRecipe {
    // Na Lua de Sangue, a Espada de Madeira some do menu de criação.
    RecipeAvailable(recipe) {
        return !(Main.bloodMoon && recipe.createItem.type === ItemID.WoodenSword);
    }

    // Com a Defesa de Exemplo, as receitas gastam metade da madeira.
    ConsumeItem(recipe, type, amount) {
        const player = Main.player[Main.myPlayer];
        if (type === ItemID.Wood && player.FindBuffIndex(ModContent.BuffType('ExampleDefenseBuff')) >= 0) {
            amount.value = Math.ceil(amount.value / 2);
        }
    }

    // O que sai da Bancada de Exemplo nasce com faíscas em volta do jogador.
    OnCraft(item, recipe) {
        if (recipe.requiredTile !== ModContent.TileType('ExampleWorkbench')) return;

        const player = Main.player[Main.myPlayer];
        for (let k = 0; k < 12; k++) {
            NewDust(player.position, player.width, player.height, DustID.GoldFlame, Rand.NextFloat(-2, 2), Rand.NextFloat(-3, -1), 0, Color.White, 1.2);
        }
    }
}

const { ItemID, NPCID, ProjectileID } = Terraria.ID;
const Main = Terraria.Main;
const WorldGen = Terraria.WorldGen;
const NewItem = Terraria.Item['int NewItem(IEntitySource source, int X, int Y, int Width, int Height, int type, int stack, bool noBroadcast, int prefix, NewItemOwnership ownership, Nullable<Vector2> velocity, Item.NewItemModifier modifier)'];
const NewProjectile = Terraria.Projectile['int NewProjectile(IEntitySource spawnSource, float X, float Y, float SpeedX, float SpeedY, int Type, int Damage, float KnockBack, int Owner, float ai0, float ai1, float ai2, NewProjectileModifier modifer)'];
const NewNPC = Terraria.NPC['int NewNPC(IEntitySource source, int X, int Y, int Type, int Start, float ai0, float ai1, float ai2, float ai3, int Target)'];

// O que cai ao sacudir uma árvore (o GlobalShakeTrees do tModLoader). Para
// a árvore de mod, o ModTree tem o Shake dele (ver ExampleTree).
export class ShakeTrees extends GlobalTile {
    // true diz que o item principal já caiu: o jogo não solta o dele.
    ShakeTree(x, y, treeType) {
        const random = WorldGen.genRand;

        // Árvore da floresta: 5% de chance de um Exemplo de Item.
        if (treeType === TreeTypes.Forest && random['int Next(int maxValue)'](20) === 0) {
            ShakeTrees.#Item(x, y, ModContent.ItemType('ExampleItem'), 1);
            return true;
        }

        // Árvore de cogumelo brilhante: 10% de chance de 3 a 10 Tochas de Cogumelo.
        if (treeType === TreeTypes.Mushroom && random['int Next(int maxValue)'](10) === 0) {
            ShakeTrees.#Item(x, y, ItemID.MushroomTorch, random['int Next(int minValue, int maxValue)'](3, 11));
            return true;
        }

        // Árvore da neve: 5% de chance de um avião de papel voando para um lado.
        if (treeType === TreeTypes.Snow && random['int Next(int maxValue)'](20) === 0) {
            NewProjectile(WorldGen.GetNPCSource_ShakeTree(x, y), x * 16, y * 16, Rand.Next(-16, 16), 0,
                ProjectileID.PaperAirplaneA, 4, 1, Main.myPlayer, 0, 0, 0, null);
            return true;
        }

        // Árvore da selva, na superfície e no Hardmode: 1 em 7 de uma Raposa Voadora Gigante.
        if (treeType === TreeTypes.Jungle && random['int Next(int maxValue)'](7) === 0 && y < Main.worldSurface && Main.hardMode) {
            NewNPC(WorldGen.GetNPCSource_ShakeTree(x, y), x * 16, y * 16, NPCID.GiantFlyingFox, 0, 0, 0, 0, 0, 255);
            return true;
        }

        if (treeType !== TreeTypes.Custom) return false;

        // Árvore de mod, à noite: metade das vezes cai um Slime de Exemplo.
        if (random['int Next(int maxValue)'](2) === 0 && !Main.dayTime) {
            NewNPC(WorldGen.GetNPCSource_ShakeTree(x, y), x * 16, y * 16, ModContent.NPCType('ExampleSlimeNPC'), 0, 0, 0, 0, 0, 255);
            return true;
        }

        // Só a Árvore de Exemplo (plantada no Bloco de Exemplo): metade das vezes, um coco.
        const bottomX = new Ref(0), bottomY = new Ref(0);
        WorldGen['void GetTreeBottom(int i, int j, out int x, out int y)'](x, y, bottomX, bottomY);
        if (bl.tiles.typeAt(bottomX.value, bottomY.value) === ModContent.TileType('ExampleTile') && random['int Next(int maxValue)'](2) === 0) {
            ShakeTrees.#Item(x, y, ItemID.Coconut, 1);
            return true;
        }

        return false;
    }

    // Antes das quedas, e sem tirar a chance delas: no mundo No Traps (e no
    // Get Fixed Boi), 20% de chance de uma flecha cair da árvore.
    PreShakeTree(x, y, treeType) {
        if (WorldGen.genRand['int Next(int maxValue)'](5) === 0 && Main.noTrapsWorld) {
            NewProjectile(WorldGen.GetNPCSource_ShakeTree(x, y), x * 16, y * 16, Rand.Next(-100, 101) * 0.002, 8,
                ProjectileID.WoodenArrowHostile, 10, 0, Main.myPlayer, 0, 0, 0, null);
        }
    }

    static #Item(x, y, type, stack) {
        NewItem(WorldGen.GetItemSource_FromTreeShake(x, y), x * 16, y * 16, 16, 16, type, stack, false, 0, 0, null, null);
    }
}

const { TileID } = Terraria.ID;

// Um GlobalTile que muda um tile do jogo (o SunflowerChanges do tModLoader):
// o Girassol passa a aceitar o Bloco de Exemplo como chão.
export class SunflowerChanges extends GlobalTile {
    SetStaticDefaults() {
        const data = Terraria.ObjectData.TileObjectData['TileObjectData GetTileData(int type, int style, int alternate)'](TileID.Sunflower, 0, 0);
        const valid = data.AnchorValidTiles;
        const exampleTile = ModContent.TileType('ExampleTile');

        const grown = valid.cloneResized(valid.length + 1);
        grown[valid.length] = exampleTile;
        data.AnchorValidTiles = grown;
    }
}

const { ItemID, TileID, ProjectileID } = Terraria.ID;
const Main = Terraria.Main;
const NewProjectile = Terraria.Projectile['int NewProjectile(IEntitySource spawnSource, Vector2 position, Vector2 velocity, int Type, int Damage, float KnockBack, int Owner, float ai0, float ai1, float ai2, NewProjectileModifier modifer)'];

export class ExampleRecipes extends ModSystem {
    static ExampleGroup = null;

    AddRecipeGroups() {
        ExampleRecipes.ExampleGroup = ModRecipe.CreateRecipeGroup('ExampleItem', [
            ModItem.getTypeByName('ExampleItem'),
            ModItem.getTypeByName('ExampleSoul'),
        ]);
    }

    AddRecipes() {
        new ModRecipe()
            .SetResult(ItemID.RodofDiscord)
            .AddIngredient(ItemID.ChaosFish, 10)
            .AddIngredient(ItemID.HallowedBar, 20)
            .AddIngredient(ItemID.SoulofFright, 5)
            .AddIngredient(ItemID.SoulofMight, 5)
            .AddIngredient(ItemID.SoulofSight, 5)
            .AddTile(TileID.MythrilAnvil)
            .Register();

        new ModRecipe()
            .SetResult(ItemID.LifeCrystal)
            .AddIngredient(ItemID.LesserHealingPotion, 50)
            .AddTile(TileID.WorkBenches)
            .Register();

        new ModRecipe()
            .SetResult(ItemID.SpikyBall, 50)
            .AddRecipeGroup('IronBar')
            .AddTile(TileID.Anvils)
            .SetProperty('needSnowBiome', true)
            .Register();

        new ModRecipe()
            .SetResult(ModItem.getTypeByName('ExampleMeleeWeapon'))
            .AddIngredient(ModItem.getTypeByName('ExampleItem'), 50)
            .AddRecipeGroup(ExampleRecipes.ExampleGroup)
            .Register();

        // Condições (as do tModLoader): no deserto, perto de água, à noite e com
        // menos da metade da vida. Fora delas, a receita some do menu de criação.
        new ModRecipe()
            .SetResult(ModItem.getTypeByName('ExampleItem'), 100)
            .AddIngredient(ItemID.StoneBlock)
            .AddIngredient(ItemID.Acorn, 10)
            .AddTile(TileID.WorkBenches)
            .AddCondition(Condition.InDesert)
            .AddCondition(Condition.NearWater)
            .AddCondition(Condition.TimeNight)
            .AddCondition('Conditions.LowHealth', () => {
                const player = Main.player[Main.myPlayer];
                return player.statLife < player.statLifeMax / 2;
            })
            .Register();

        // A Corrente é pedida mas não é gasta, como a Mesa de Alquimia faz com as poções.
        new ModRecipe()
            .SetResult(ItemID.AlphabetStatueJ)
            .AddIngredient(ItemID.StoneBlock, 10)
            .AddIngredient(ItemID.Chain)
            .AddConsumeIngredientCallback(ExampleRecipes.DontConsumeChain)
            .AddTile(TileID.HeavyWorkBench)
            .Register();

        // Código depois de criar: às vezes, fogos de artifício.
        new ModRecipe()
            .SetResult(ItemID.AlphabetStatueZ)
            .AddIngredient(ItemID.StoneBlock, 10)
            .AddIngredient(ItemID.Chain)
            .AddOnCraftCallback(ExampleRecipes.RandomlySpawnFireworks)
            .AddTile(TileID.HeavyWorkBench)
            .Register();
    }

    // amount é Ref: 0 = o ingrediente não sai.
    static DontConsumeChain(recipe, type, amount, isDecrafting) {
        if (type === ItemID.Chain) amount.value = 0;
    }

    static RandomlySpawnFireworks(recipe, item, consumedItems, destinationStack) {
        if (!Rand.NextBool(3)) return;

        const player = Main.player[Main.myPlayer];
        const firework = ProjectileID.RocketFireworksBoxRed + Rand.Next(4);
        const velocity = Vector2.RotatedByRandom(Vector2.new(0, -Rand.NextFloat(2, 4)), 0.3);
        NewProjectile(player.GetProjectileSource_Item(item), player.Top, velocity, firework, 0, 0, Main.myPlayer, 0, 0, 0, null);
        player['void QuickSpawnItem(IEntitySource source, int item, int stack)'](player.GetItemSource_Misc(0), ItemID.Confetti, 5);
    }
}
